//! A permanent scrollbar for a scrolling list, as a narrow column beside it:
//! a square button at the top that scrolls up, a track whose thumb shows how
//! much of the list is in view and can be dragged or clicked to, and a square
//! button at the bottom that scrolls down. Lists that follow new output, like
//! a task's, add a button below that locks the scroll to the bottom.

use std::cell::Cell;
use std::rc::Rc;
use std::time::{Duration, Instant};

use gpui_kit::component::{ActiveTheme as _, h_flex, v_flex};
use gpui_kit::prelude::FluentBuilder as _;
use gpui_kit::*;

use crate::measured_list::MeasuredList;

/// How wide the column is, which is also each button's width.
pub const COLUMN_WIDTH: Pixels = px(18.);

/// How far a button scrolls the list.
const STEP: Pixels = px(48.);

/// The shortest the thumb gets, so it can always be grabbed.
const MIN_THUMB: Pixels = px(16.);

/// How long the pulse lasts when the scroll locks.
const PULSE_TIME: Duration = Duration::from_millis(900);

/// What a scroll column scrolls: an element tracking a [`ScrollHandle`], or a
/// virtualized list that knows its rows' heights.
/// Locks the scroll to the bottom (`true`) or unlocks it (`false`).
pub type SetLock = Rc<dyn Fn(bool, &mut Window, &mut App)>;

/// `content`, which scrolls with `handle`, beside its scroll column. With
/// `fill`, it fills the space it is given; otherwise it is as tall as
/// `content`, which is expected to cap its own height. With `lock`, whether
/// the scroll is locked to the bottom and how to switch it, the column ends in
/// a button for that; scrolling the list by hand, with the wheel or the
/// column, locks it when that leaves the list at the bottom and breaks the lock
/// when it doesn't.
pub fn with_scrollbar(
    id: impl Into<SharedString>,
    handle: impl Into<Scroll>,
    content: impl IntoElement,
    fill: bool,
    lock: Option<(bool, SetLock)>,
    cx: &App,
) -> AnyElement {
    let handle: Scroll = handle.into();
    let follow = follower(&handle, &lock);
    let row = h_flex()
        .items_stretch()
        .w_full()
        .when(fill, |row| row.flex_1().min_h_0().h_full())
        .child(
            div()
                .flex_1()
                .min_w_0()
                .when(fill, |it| it.h_full())
                // Scrolling by hand locks or unlocks the scroll. This bubbles
                // up from the list, which has already taken the scroll.
                .when_some(follow, |content, follow| {
                    content.on_scroll_wheel(move |_, window, cx| follow(window, cx))
                })
                .child(content),
        )
        .child(scrollbar(id.into(), &handle, lock, Axis::Vertical, cx));
    row.into_any_element()
}

/// `content`, which scrolls with `handle`, beside its scroll column, as tall
/// as `content` until the flex column it is in gives it less, when it shrinks
/// and `content` scrolls. `content` is expected to shrink too.
pub fn with_fitted_scrollbar(
    id: impl Into<SharedString>,
    handle: impl Into<Scroll>,
    content: impl IntoElement,
    cx: &App,
) -> AnyElement {
    let handle: Scroll = handle.into();
    h_flex()
        .items_stretch()
        .w_full()
        .flex_shrink(1.)
        .min_h_0()
        .child(v_flex().flex_1().min_w_0().min_h_0().child(content))
        .child(scrollbar(id.into(), &handle, None, Axis::Vertical, cx))
        .into_any_element()
}

/// `content`, which scrolls sideways with `handle`, above its scrollbar,
/// laid along its foot as a column is along a list's right: a button at the
/// left that scrolls left, the track, and a button at the right that scrolls
/// right. It fills the space it is given.
pub fn with_horizontal_scrollbar(
    id: impl Into<SharedString>,
    handle: &ScrollHandle,
    content: impl IntoElement,
    cx: &App,
) -> AnyElement {
    let handle: Scroll = handle.into();
    v_flex()
        .size_full()
        .min_h_0()
        .child(div().flex_1().min_h_0().w_full().child(content))
        .child(scrollbar(id.into(), &handle, None, Axis::Horizontal, cx))
        .into_any_element()
}

/// `bounds` laid out as a column's are: a bar along a list's foot turned on
/// its side, so its left is a column's top. Turning it again turns it back.
fn across(axis: Axis, bounds: Bounds<Pixels>) -> Bounds<Pixels> {
    match axis {
        Axis::Vertical => bounds,
        Axis::Horizontal => Bounds::new(
            point(bounds.origin.y, bounds.origin.x),
            size(bounds.size.height, bounds.size.width),
        ),
    }
}

/// `at` laid out as a column's points are, as [`across`] lays out bounds.
fn across_point(axis: Axis, at: Point<Pixels>) -> Point<Pixels> {
    match axis {
        Axis::Vertical => at,
        Axis::Horizontal => point(at.y, at.x),
    }
}

/// After the list is scrolled by hand: locks the scroll when the list is left
/// at the bottom, and unlocks it when it isn't. A list with nothing to scroll
/// keeps its lock as it is.
type Follow = Rc<dyn Fn(&mut Window, &mut App)>;

fn follower(handle: &Scroll, lock: &Option<(bool, SetLock)>) -> Option<Follow> {
    let (_, set_lock) = lock.as_ref()?;
    let (handle, set_lock) = (handle.clone(), set_lock.clone());
    Some(Rc::new(move |window, cx| {
        let max = handle.max_offset().y;
        if max > px(0.) {
            set_lock(at_bottom(&handle), window, cx);
        }
    }))
}

/// Whether the list is scrolled to its bottom, or past it before it is
/// clamped.
fn at_bottom(handle: &Scroll) -> bool {
    handle.offset().y <= -handle.max_offset().y + px(1.)
}

/// How tall each button is.
pub const BUTTON_HEIGHT: Pixels = px(17.);

/// How far the track is inset from either side of the column.
const TRACK_INSET: Pixels = px(1.);

/// The column itself: no background of its own, so its track is the colour of
/// whatever it sits on, with a line around it, the buttons, and the thumb
/// raised over that.
fn scrollbar(
    id: SharedString,
    handle: &Scroll,
    lock: Option<(bool, SetLock)>,
    axis: Axis,
    cx: &App,
) -> AnyElement {
    let colors = scroll_colors(cx.theme().is_dark());
    let follow = follower(handle, &lock);
    let scroll_by = |delta: Pixels| {
        let handle = handle.clone();
        let follow = follow.clone();
        let press: Press = Rc::new(move |window: &mut Window, cx: &mut App| {
            let offset = handle.offset();
            let max = handle.max_offset().along(axis);
            handle.set_offset(offset.apply_along(axis, |at| (at + delta).min(px(0.)).max(-max)));
            if let Some(follow) = &follow {
                follow(window, cx);
            }
            window.refresh();
        });
        press
    };

    let track = canvas(
        // Where on the thumb it was grabbed, while it is being dragged. Kept
        // with the track from frame to frame, since each mouse move redraws
        // the column.
        |_, window, cx| {
            let grab = window
                .use_keyed_state("scroll-grab", cx, |_, _| Rc::new(Cell::new(None::<Pixels>)));
            // Whether the pointer was over the thumb when last drawn.
            let hovered =
                window.use_keyed_state("scroll-thumb-hover", cx, |_, _| Rc::new(Cell::new(false)));
            (grab, hovered)
        },
        {
            let handle = handle.clone();
            let follow = follow.clone();
            move |bounds,
                  (grab, hovered): (Entity<Rc<Cell<Option<Pixels>>>>, Entity<Rc<Cell<bool>>>),
                  window,
                  cx| {
                let grab = grab.read(cx).clone();
                let hovered = hovered.read(cx).clone();
                // Worked out as a column's, and turned back to be drawn.
                let shown = bounds;
                let bounds = across(axis, bounds);
                let geometry = Geometry::along(&handle, bounds, axis);
                let thumb = thumb_bounds(&geometry, bounds);
                let pointer = across_point(axis, window.mouse_position());
                // The track is the surface, with the column's line down either
                // side of it, and the thumb raised across the column's full
                // width, the line and all, between its ends: a pixel at each
                // end, between the track's colour and the thumb's, across the
                // track. Nothing is laid twice.
                let (body, ends) = thumb_ends(thumb, bounds, &colors);
                for (top, bottom) in [(bounds.top(), body.top()), (body.bottom(), bounds.bottom())]
                {
                    for side in sides(bounds, top, bottom) {
                        window.paint_quad(fill(across(axis, side), colors.raised));
                    }
                }
                window.paint_quad(fill(across(axis, body), colors.raised));
                for (end, color) in ends {
                    window.paint_quad(fill(across(axis, end), color));
                }
                // Lightening while hovered or dragged. Nothing is hovered
                // while something else, like a sidebar's edge, is being
                // dragged across it.
                let is_hovered = !cx.has_active_drag() && thumb.contains(&pointer);
                hovered.set(is_hovered);
                if grab.get().is_some() {
                    // No edge beneath the pointer is offered while dragging.
                    window.set_window_cursor_style(CursorStyle::Arrow);
                    window.paint_quad(fill(across(axis, thumb), colors.pressed));
                } else if is_hovered {
                    window.paint_quad(fill(across(axis, thumb), colors.hover));
                }
                // Moving on or off the thumb redraws it.
                window.on_mouse_event({
                    let (handle, hovered) = (handle.clone(), hovered.clone());
                    move |event: &MouseMoveEvent, _, window, _| {
                        let geometry = Geometry::along(&handle, bounds, axis);
                        let thumb = thumb_bounds(&geometry, bounds);
                        if thumb.contains(&across_point(axis, event.position)) != hovered.get() {
                            window.refresh();
                        }
                    }
                });

                window.on_mouse_event({
                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
                    move |event: &MouseDownEvent, phase, window, cx| {
                        if !shown.contains(&event.position) {
                            return;
                        }
                        let geometry = Geometry::along(&handle, bounds, axis);
                        let y = across_point(axis, event.position).y;
                        // The thumb, or the track pressed off it, against any
                        // resize edge over it there: the smaller takes the
                        // press, taking it first when it is contested.
                        let on_thumb = y >= geometry.thumb_top
                            && y <= geometry.thumb_top + geometry.thumb_height;
                        let target = if on_thumb {
                            across(axis, thumb_bounds(&geometry, bounds))
                        } else {
                            shown
                        };
                        if !crate::hit_areas::wins_at(target, event.position, cx) {
                            return;
                        }
                        let contested = crate::hit_areas::resize_at(event.position, cx);
                        let turn = if contested {
                            DispatchPhase::Capture
                        } else {
                            DispatchPhase::Bubble
                        };
                        if phase != turn {
                            return;
                        }
                        if contested {
                            cx.stop_propagation();
                        }
                        // Grabbed where it was pressed; pressed off the thumb, the
                        // thumb first jumps to centre on the press.
                        let at = if on_thumb {
                            y - geometry.thumb_top
                        } else {
                            geometry.thumb_height / 2.
                        };
                        grab.set(Some(at));
                        geometry.scroll_thumb_to(&handle, y - at);
                        if let Some(follow) = &follow {
                            follow(window, cx);
                        }
                        window.refresh();
                    }
                });
                window.on_mouse_event({
                    let (handle, grab, follow) = (handle.clone(), grab.clone(), follow.clone());
                    move |event: &MouseMoveEvent, _, window, cx| {
                        if let Some(at) = grab.get() {
                            if !event.dragging() {
                                grab.set(None);
                                return;
                            }
                            Geometry::along(&handle, bounds, axis).scroll_thumb_to(
                                &handle,
                                across_point(axis, event.position).y - at,
                            );
                            if let Some(follow) = &follow {
                                follow(window, cx);
                            }
                            window.refresh();
                        }
                    }
                });
                window.on_mouse_event({
                    let grab = grab.clone();
                    move |_: &MouseUpEvent, _, _, _| grab.set(None)
                });
            }
        },
    )
    .size_full();

    let (before, after) = match axis {
        Axis::Vertical => ("Scroll up", "Scroll down"),
        Axis::Horizontal => ("Scroll left", "Scroll right"),
    };
    let column = match axis {
        Axis::Vertical => v_flex().w(COLUMN_WIDTH),
        Axis::Horizontal => h_flex().h(COLUMN_WIDTH),
    };
    let column = column
        .id(SharedString::from(format!("{id}-scroll-column")))
        .flex_none()
        .child(square(
            format!("{id}-scroll-up"),
            Glyph::Up,
            before.into(),
            false,
            scroll_by(STEP),
            None,
            axis,
            colors,
        ))
        .child(gpui_kit::TestSupportExt::test_support(
            div()
                .id(SharedString::from(format!("{id}-scroll-track")))
                .flex_1()
                .when(axis == Axis::Vertical, |track| track.min_h(px(8.)))
                .when(axis == Axis::Horizontal, |track| track.min_w(px(8.)))
                .child(track),
        ))
        .child(square(
            format!("{id}-scroll-down"),
            Glyph::Down,
            after.into(),
            false,
            scroll_by(-STEP),
            None,
            axis,
            colors,
        ))
        .when_some(lock, |column, (locked, set_lock)| {
            let press: Press = Rc::new(move |window, cx| set_lock(!locked, window, cx));
            let tooltip = if locked {
                "Unlock the scroll from the bottom"
            } else {
                "Lock the scroll to the bottom"
            };
            column
                // A pixel of the surface between it and the down button,
                // within the column's line.
                .child(
                    canvas(
                        |_, _, _| {},
                        move |bounds, _, window, _| {
                            for side in sides(bounds, bounds.top(), bounds.bottom()) {
                                window.paint_quad(fill(side, colors.raised));
                            }
                        },
                    )
                    .flex_none()
                    .w(COLUMN_WIDTH)
                    .h(LOCK_GAP),
                )
                .child(square(
                    format!("{id}-scroll-lock"),
                    Glyph::ToBottom,
                    tooltip.into(),
                    locked,
                    press,
                    Some(pulse(locked, cx).into_any_element()),
                    axis,
                    colors,
                ))
        });
    // Lets UI tests find the column; inert in normal builds.
    gpui_kit::TestSupportExt::test_support(column).into_any_element()
}

/// The space between the down button and the lock button.
const LOCK_GAP: Pixels = px(1.);

/// Where the track lies across a column at `bounds`: its left and its width,
/// a pixel in from either side.
fn inset(bounds: Bounds<Pixels>) -> (Pixels, Pixels) {
    (
        bounds.origin.x + TRACK_INSET,
        (bounds.size.width - TRACK_INSET * 2.).max(px(0.)),
    )
}

/// The column's line down either side of a column at `bounds`, from `top` to
/// `bottom`: none where there is no height between them.
fn sides(bounds: Bounds<Pixels>, top: Pixels, bottom: Pixels) -> Vec<Bounds<Pixels>> {
    if bottom <= top {
        return Vec::new();
    }
    let height = bottom - top;
    vec![
        Bounds::new(point(bounds.left(), top), size(TRACK_INSET, height)),
        Bounds::new(
            point(bounds.right() - TRACK_INSET, top),
            size(TRACK_INSET, height),
        ),
    ]
}

/// A thumb at `thumb`, in a track at `track`, split into the part raised
/// across the column's full width, and the single row at each end, across the
/// track's width, with its colour. With the thumb too short to have two ends,
/// all of it is raised.
fn thumb_ends(
    thumb: Bounds<Pixels>,
    track: Bounds<Pixels>,
    colors: &ScrollColors,
) -> (Bounds<Pixels>, Vec<(Bounds<Pixels>, Hsla)>) {
    let row = px(1.);
    if thumb.size.height < row * 2. {
        return (thumb, Vec::new());
    }
    let (left, width) = inset(track);
    let body = Bounds::new(
        point(thumb.left(), thumb.top() + row),
        size(thumb.size.width, thumb.size.height - row * 2.),
    );
    let ends = vec![
        (
            Bounds::new(point(left, thumb.top()), size(width, row)),
            colors.thumb_end,
        ),
        (
            Bounds::new(point(left, thumb.bottom() - row), size(width, row)),
            colors.thumb_end,
        ),
    ];
    (body, ends)
}

/// What a button in the column shows: a small solid arrow, pointing up or
/// down, or down to a line for the lock.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Glyph {
    Up,
    Down,
    ToBottom,
}

impl Glyph {
    /// The glyph's rows in a button at `bounds`, each as its top and width
    /// from the button's top, centred across it: a triangle 6 pixels wide
    /// and 4 tall, 7 pixels from the button's top pointing up or from its
    /// bottom pointing down, and for the lock the down arrow with a bar
    /// beneath it.
    fn rows(self) -> &'static [(f32, f32)] {
        match self {
            Glyph::Up => &[(7., 2.), (8., 4.), (9., 6.), (10., 6.)],
            Glyph::Down => &[(6., 6.), (7., 6.), (8., 4.), (9., 2.)],
            Glyph::ToBottom => &[(5., 6.), (6., 6.), (7., 4.), (8., 2.), (10., 6.)],
        }
    }

    pub(crate) fn quads(self, bounds: Bounds<Pixels>) -> Vec<Bounds<Pixels>> {
        // Rounded to a whole pixel, so it stays crisp.
        let center = (bounds.origin.x + bounds.size.width / 2.).round();
        self.rows()
            .iter()
            .map(|&(top, width)| {
                Bounds::new(
                    point(center - px(width / 2.), bounds.origin.y + px(top)),
                    size(px(width), px(1.)),
                )
            })
            .collect()
    }
}

/// A button in the column, `id`, as wide as the column and a button tall,
/// raised over the surface as the thumb is, showing `glyph`, with no bevel. It
/// lightens as the thumb does while hovered, and again while pressed with the
/// pointer still over it, or while `selected`. Pressing it does `press`.
/// `behind` is drawn beneath everything else in it.
fn square(
    id: String,
    glyph: Glyph,
    tooltip: SharedString,
    selected: bool,
    press: Press,
    behind: Option<AnyElement>,
    axis: Axis,
    colors: ScrollColors,
) -> impl IntoElement {
    // Along a list's foot, the column's arrows turned on their side.
    let arrow = canvas(
        |_, _, _| {},
        move |bounds, _, window, _| {
            for row in glyph.quads(across(axis, bounds)) {
                window.paint_quad(fill(across(axis, row), colors.arrow));
            }
        },
    )
    .absolute()
    .top_0()
    .left_0()
    .size_full();
    let button = div()
        .id(SharedString::from(id.clone()))
        .relative()
        .flex_none()
        .map(|button| match axis {
            Axis::Vertical => button.w(COLUMN_WIDTH).h(BUTTON_HEIGHT),
            Axis::Horizontal => button.w(BUTTON_HEIGHT).h(COLUMN_WIDTH),
        })
        .children(behind)
        .child(face(format!("{id}-face"), selected, colors))
        .child(arrow)
        .child(over_edges(format!("{id}-claim").into(), press.clone()))
        .tooltip(move |window, cx| {
            gpui_kit::component::tooltip::Tooltip::new(tooltip.clone()).build(window, cx)
        })
        .on_click(move |_, window, cx| press(window, cx));
    // Lets UI tests find the button; inert in normal builds.
    gpui_kit::TestSupportExt::test_support(button)
}

/// A button's face: raised over the surface, lightened while hovered, and
/// again while pressed with the pointer still over it, or while `selected`.
/// It takes no mouse: it watches the mouse before the button does.
fn face(key: String, selected: bool, colors: ScrollColors) -> impl IntoElement {
    let key = SharedString::from(key);
    canvas(
        move |_, window, cx| {
            // Whether the button was pressed, and not yet let go.
            window.use_keyed_state(key, cx, |_, _| Rc::new(Cell::new(false)))
        },
        move |bounds, pressed: Entity<Rc<Cell<bool>>>, window, cx| {
            let pressed = pressed.read(cx).clone();
            // Not while something else, like a sidebar's edge, is dragged.
            let hovered = !cx.has_active_drag() && bounds.contains(&window.mouse_position());
            window.paint_quad(fill(bounds, colors.raised));
