                    "{c:06x} at ({x}, -1), between the buttons"
                );
            }
            let mut lit = 0;
            for y in 0..17 {
                for x in 0..18 {
                    let c = at(x, y);
                    if same(c, arrow) {
                        lit += 1;
                    } else {
                        assert!(same(c, raised), "{c:06x} at ({x}, {y}) in the lock button");
                    }
                }
            }
            assert!(lit > 0, "the lock button shows nothing");
        })
